`timescale 1ns/1ps
// Synthesizable fixture runner. ROMs are generated by the independent Python
// direct-parity reference; the numerical core is unchanged.
module adhd_board_test #(parameter integer CLASSES=10)(
    input wire clk, input wire resetn,
    output wire [31:0] status,
    output reg [31:0] errors=0, checked=0,
    output reg [31:0] result0=0, result1=0, result2=0, result3=0,
    output wire [31:0] core_cycles
);
    localparam INIT=0, MFETCH=1, MWRITE=2, FFETCH=3, FWRITE=4,
        START=5, RUN=6, HOLD=7, ACCEPT=8, NEXT=9, DONE=10,
        ABORT_START=11, ABORT_RUN=12, ABORT_RESET=13;
    reg [3:0] state=INIT;
    reg [1:0] test_case=0;
    reg [12:0] ptr=0;
    reg [7:0] fptr=0;
    reg [3:0] hold_count=0;
    reg [3:0] passes=0;
    reg [31:0] watchdog=0;
    reg [13:0] qcount=0;
    (* ram_style="block" *) reg [CLASSES+3:0] model_rom [0:32767];
    reg [1:0] feature_rom [0:783];
    (* ram_style="block" *) reg [0:0] query_rom [0:32767];
    reg [31:0] expected_rom [0:3];
    initial begin
        $readmemh("board_model.hex",model_rom);
        $readmemh("board_features.hex",feature_rom);
        $readmemh("board_query.hex",query_rom);
        $readmemh("board_expected.hex",expected_rom);
    end
    reg [CLASSES+3:0] model_word;
    reg [1:0] feature_word;
    wire ready,busy,result_valid,query_valid,query_bit;
    wire [12:0] query_addr;
    wire [4:0] result_class;
    wire [13:0] result_score;
    reg golden_q, sampled_q, sampled_valid=0;
    reg [12:0] sampled_addr;
    wire core_resetn=resetn && state!=INIT && state!=ABORT_RESET;
    wire guard_write=state==RUN && test_case==0 && core_cycles==10;
    wire [31:0] packed_result={11'b0,result_class,2'b0,result_score};
    assign status={16'hADCD,6'b0,test_case,passes,(state==DONE),
                   (errors!=0),busy,ready};
    adhd_hdc #(.CLASSES(CLASSES)) core(
        .clk(clk),.resetn(core_resetn),
        .model_we(state==MWRITE || guard_write),.model_addr(ptr),
        .model_data(guard_write?32'b0:{{(28-CLASSES){1'b0}},model_word}),
        .feature_we(state==FWRITE || guard_write),.feature_addr(fptr),
        .feature_data(guard_write?2'b0:feature_word),
        .start(state==START || state==ABORT_START || guard_write),
        .ready(ready),.busy(busy),.result_valid(result_valid),
        .result_ready(state==ACCEPT),.result_class(result_class),
        .result_score(result_score),.cycles(core_cycles),
        .query_valid(query_valid),.query_addr(query_addr),.query_bit(query_bit));
    always @(posedge clk) begin
        model_word<=model_rom[{test_case,ptr}];
        feature_word<=feature_rom[test_case*196+fptr];
        golden_q<=query_rom[{test_case,query_addr}];
        sampled_q<=query_bit;
        sampled_addr<=query_addr;
        sampled_valid<=query_valid && (state==RUN || state==HOLD);
        if(!resetn) begin
            state<=INIT;test_case<=0;ptr<=0;fptr<=0;hold_count<=0;
            passes<=0;errors<=0;checked<=0;qcount<=0;watchdog<=0;
            sampled_valid<=0;result0<=0;result1<=0;result2<=0;result3<=0;
        end else begin
            if(state!=DONE) watchdog<=watchdog+1;
            if(sampled_valid) begin
                checked<=checked+1;qcount<=qcount+1;
                if(sampled_q!=golden_q || sampled_addr!=(qcount[12:0]^(qcount[12:0]>>1)))
                    errors<=errors+1;
            end
            case(state)
                INIT: state<=MFETCH;
                MFETCH: state<=MWRITE;
                MWRITE: if(ptr==8191) begin fptr<=0;state<=FFETCH;end
                        else begin ptr<=ptr+1;state<=MFETCH;end
                FFETCH: state<=FWRITE;
                FWRITE: if(fptr==195) state<=(test_case==0)?ABORT_START:START;
                        else begin fptr<=fptr+1;state<=FFETCH;end
                ABORT_START: state<=ABORT_RUN;
                ABORT_RUN: if(core_cycles==17) state<=ABORT_RESET;
                ABORT_RESET: state<=START;
                START: begin qcount<=0;state<=RUN;end
                RUN: if(result_valid) begin hold_count<=0;state<=HOLD;end
                HOLD: begin
                    if(!result_valid || packed_result!=expected_rom[test_case] ||
                       core_cycles!=8192+5+CLASSES || qcount!=8192)
                        errors<=errors+1;
                    if(hold_count==7) begin
                        if(errors==0) passes[test_case]<=1;
                        case(test_case)
                            0: result0<=packed_result; 1: result1<=packed_result;
                            2: result2<=packed_result; 3: result3<=packed_result;
                        endcase
                        state<=ACCEPT;
                    end else hold_count<=hold_count+1;
                end
                ACCEPT: state<=NEXT;
                NEXT: if(test_case==3) state<=DONE;
                      else begin test_case<=test_case+1;ptr<=0;state<=MFETCH;end
                DONE: state<=DONE;
                default: begin errors<=errors+1;state<=DONE;end
            endcase
            if(watchdog==200000) begin errors<=errors+1;state<=DONE;end
        end
    end
endmodule
